// Compatibility with the service: the vectors are generated by Python
// (packages/sdk-ts/scripts/gen_vectors.py), which is the reference.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  GENESIS, canonicalJson, computeEventHash, fromBase64, hashPayload,
  toBase64, verify,
} from './index';

const V = JSON.parse(
  readFileSync(new URL('../../test-vectors.json', import.meta.url), 'utf-8'));
const hex = (s: string) => new Uint8Array(Buffer.from(s, 'hex'));

describe('compatibility with the Python service', () => {
  it('GENESIS matches', () => {
    expect(Buffer.from(GENESIS).toString('hex')).toBe(V.genesis_hex);
  });
  for (const c of V.canonical) {
    it(`canonicalJson: ${c.name}`, () => {
      expect(canonicalJson(c.value)).toBe(c.expected);
    });
  }
  for (const c of V.hash_payload) {
    it(`hashPayload: ${c.name}`, () => {
      expect(hashPayload(c.value)).toBe(c.expected);
    });
  }
  for (const c of V.base64) {
    it(`toBase64: ${c.name}`, () => {
      expect(toBase64(hex(c.hex))).toBe(c.expected);
    });
    it(`fromBase64: ${c.name}`, () => {
      expect(Buffer.from(fromBase64(c.expected)).toString('hex')).toBe(c.hex);
    });
  }
  it('event hash', () => {
    const e = V.event_hash;
    expect(computeEventHash(e.prev_hash, e.payload_hash, e.material))
      .toBe(e.expected);
  });
  it('verifies an Ed25519 signature made in Python', () => {
    const k = V.ed25519;
    expect(verify(hex(k.public_hex), hex(k.message_hex),
                  hex(k.signature_hex))).toBe(true);
  });
});
